import{_ as i,a0 as o,w as r,s as d,ao as t,I as a,x as n,a1 as l,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"GraphQL 用例：使用 Golang 和 PostgreSQL 構建一個Blog引擎 API | LCTT x X-CMD","titleTemplate":false,"description":"GraphQL 用例：使用 Golang 和 PostgreSQL 構建一個Blog引擎 API | LCTT (201705) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"GraphQL 用例：使用 Golang 和 PostgreSQL 構建一個Blog引擎 API | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"GraphQL 用例：使用 Golang 和 PostgreSQL 構建一個Blog引擎 API | LCTT (201705) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201705/20170101 GraphQL In Use Building a Blogging Engine API with Golang and PostgreSQL","title":"GraphQL 用例：使用 Golang 和 PostgreSQL 構建一個Blog引擎 API","tag":"201705","desc":""},"relativePath":"201705/20170101 GraphQL In Use Building a Blogging Engine API with Golang and PostgreSQL.md","filePath":"[post].md"}'),c={name:"201705/20170101 GraphQL In Use Building a Blogging Engine API with Golang and PostgreSQL.md"};function g(u,s,m,h,T,S){const p=o("Link");return r(),d("div",null,[s[36]||(s[36]=t('<h1 id="graphql-用例-使用-golang-和-postgresql-構建一個blog引擎-api" tabindex="-1">GraphQL 用例：使用 Golang 和 PostgreSQL 構建一個Blog引擎 API <a class="header-anchor" href="#graphql-用例-使用-golang-和-postgresql-構建一個blog引擎-api" aria-label="Permalink to “GraphQL 用例：使用 Golang 和 PostgreSQL 構建一個Blog引擎 API”">​</a></h1><h3 id="摘要" tabindex="-1">摘要 <a class="header-anchor" href="#摘要" aria-label="Permalink to “摘要”">​</a></h3><p>GraphQL 在生產環境中似乎難以使用：雖然對於建模功能來説圖接口非常靈活，但是並不適用於關係型存儲，不管是在實現還是性能方面。</p><p>在這篇Blog中，我們會設計並實現一個簡單的Blog引擎 API，它支持以下功能：</p><ul><li>三種類型的資源（用户、博文以及評論）支持多種功能（創建用户、創建博文、給博文添加評論、關注其它用户的博文和評論，等等。）</li><li>使用 PostgreSQL 作為後端數據存儲（選擇它因為它是一個流行的關係型資料庫）。</li><li>使用 Golang（開發 API 的一個流行語言）實現 API。</li></ul><p>我們會比較簡單的 GraphQL 實現和純 REST 替代方案，在一種普通場景（呈現Blog文章頁面）下對比它們的實現複雜性和效率。</p><h3 id="介紹" tabindex="-1">介紹 <a class="header-anchor" href="#介紹" aria-label="Permalink to “介紹”">​</a></h3><p>GraphQL 是一種 IDL（Interface Definition Language，接口定義語言），設計者定義數據類型和並把數據建模為一個圖（graph）。每個頂點都是一種數據類型的一個實例，邊代表了節點之間的關係。這種方式非常靈活，能適應任何業務領域。然而，問題是設計過程更加複雜，而且傳統的數據存儲不能很好地映射到圖模型。閲讀_附錄1_瞭解更多關於這個問題的詳細信息。</p><p>GraphQL 在 2014 年由 Facebook 的工程師團隊首次提出。儘管它的優點和功能非常有趣而且引人注目，但它並沒有得到大規模應用。開發者需要權衡 REST 的設計簡單性、熟悉性、豐富的工具和 GraphQL 不會受限於 CRUD（LCTT 譯註：Create、Read、Update、Delete） 以及網絡性能（它優化了往返服務器的網絡）的靈活性。</p><p>大部分關於 GraphQL 的教程和指南都跳過了從數據存儲獲取數據以便解決查詢的問題。也就是，如何使用通用目的、流行存儲方案（例如關係型資料庫）為 GraphQL API 設計一個支持高效數據提取的資料庫。</p><p>這篇Blog介紹構建一個Blog引擎 GraphQL API 的流程。它的功能相當複雜。為了和基於 REST 的方法進行比較，它的範圍被限制為一個熟悉的業務領域。</p><p>這篇Blog的文章結構如下：</p><ul><li>第一部分我們會設計一個 GraphQL 模式並介紹所使用語言的一些功能。</li><li>第二部分是 PostgreSQL 資料庫的設計。</li><li>第三部分介紹了使用 Golang 實現第一部分設計的 GraphQL 模式。</li><li>第四部分我們以從後端獲取所需數據的角度來比較呈現Blog文章頁面的任務。</li></ul><h3 id="相關閲讀" tabindex="-1">相關閲讀 <a class="header-anchor" href="#相關閲讀" aria-label="Permalink to “相關閲讀”">​</a></h3>',14)),a("ul",null,[a("li",null,[s[1]||(s[1]=n("很棒的 ",-1)),l(p,{href:"http://graphql.org/learn/"},{default:e(()=>[...s[0]||(s[0]=[n("GraphQL 介紹文檔",-1)])]),_:1}),s[2]||(s[2]=n("。",-1))]),a("li",null,[s[4]||(s[4]=n("該項目的完整實現代碼在 ",-1)),l(p,{href:"https://github.com/topliceanu/graphql-go-example"},{default:e(()=>[...s[3]||(s[3]=[n("github.com/topliceanu/graphql-go-example",-1)])]),_:1}),s[5]||(s[5]=n("。",-1))])]),s[37]||(s[37]=t(`<h3 id="在-graphql-中建模一個blog引擎" tabindex="-1">在 GraphQL 中建模一個Blog引擎 <a class="header-anchor" href="#在-graphql-中建模一個blog引擎" aria-label="Permalink to “在 GraphQL 中建模一個Blog引擎”">​</a></h3><p>下述_列表1_包括了Blog引擎 API 的全部模式。它顯示了組成圖的頂點的數據類型。頂點之間的關係，也就是邊，被建模為指定類型的屬性。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>type User {</span></span>
<span class="line"><span>  id: ID</span></span>
<span class="line"><span>  email: String!</span></span>
<span class="line"><span>  post(id: ID!): Post</span></span>
<span class="line"><span>  posts: [Post!]!</span></span>
<span class="line"><span>  follower(id: ID!): User</span></span>
<span class="line"><span>  followers: [User!]!</span></span>
<span class="line"><span>  followee(id: ID!): User</span></span>
<span class="line"><span>  followees: [User!]!</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>type Post {</span></span>
<span class="line"><span>  id: ID</span></span>
<span class="line"><span>  user: User!</span></span>
<span class="line"><span>  title: String!</span></span>
<span class="line"><span>  body: String!</span></span>
<span class="line"><span>  comment(id: ID!): Comment</span></span>
<span class="line"><span>  comments: [Comment!]!</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>type Comment {</span></span>
<span class="line"><span>  id: ID</span></span>
<span class="line"><span>  user: User!</span></span>
<span class="line"><span>  post: Post!</span></span>
<span class="line"><span>  title: String</span></span>
<span class="line"><span>  body: String!</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>type Query {</span></span>
<span class="line"><span>  user(id: ID!): User</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>type Mutation {</span></span>
<span class="line"><span>  createUser(email: String!): User</span></span>
<span class="line"><span>  removeUser(id: ID!): Boolean</span></span>
<span class="line"><span>  follow(follower: ID!, followee: ID!): Boolean</span></span>
<span class="line"><span>  unfollow(follower: ID!, followee: ID!): Boolean</span></span>
<span class="line"><span>  createPost(user: ID!, title: String!, body: String!): Post</span></span>
<span class="line"><span>  removePost(id: ID!): Boolean</span></span>
<span class="line"><span>  createComment(user: ID!, post: ID!, title: String!, body: String!): Comment</span></span>
<span class="line"><span>  removeComment(id: ID!): Boolean</span></span>
<span class="line"><span>}</span></span></code></pre></div><p><em>列表1</em></p><p>模式使用 GraphQL DSL 編寫，它用於定義自定義數據類型，例如 <code>User</code>、<code>Post</code> 和 <code>Comment</code>。該語言也提供了一系列原始數據類型，例如 <code>String</code>、<code>Boolean</code> 和 <code>ID</code>（它是<code>String</code> 的別名，但是有頂點唯一標識符的額外語義）。</p><p><code>Query</code> 和 <code>Mutation</code> 是語法解析器能識別並用於查詢圖的可選類型。從 GraphQL API 讀取數據等同於遍歷圖。需要提供這樣一個起始頂點；該角色通過 <code>Query</code> 類型來實現。在這種情況中，所有圖的查詢都要從一個由 id <code>user(id:ID!)</code> 指定的用户開始。對於寫數據，定義了 <code>Mutation</code> 頂點。它提供了一系列操作，建模為能遍歷（並返回）新創建頂點類型的參數化屬性。_列表2_是這些查詢的一些例子。</p><p>頂點屬性能被參數化，也就是能接受參數。在圖遍歷場景中，如果一個博文頂點有多個評論頂點，你可以通過指定 <code>comment(id: ID)</code> 只遍歷其中的一個。所有這些都取決於設計，設計者可以選擇不提供到每個獨立頂點的直接路徑。</p><p><code>!</code> 字符是一個類型後綴，適用於原始類型和用户定義類型，它有兩種語義：</p><ul><li>當被用於參數化屬性的參數類型時，表示這個參數是必須的。</li><li>當被用於一個屬性的返回類型時，表示當頂點被獲取時該屬性不會為空。</li><li>也可以把它們組合起來，例如 <code>[Comment!]!</code> 表示一個非空 Comment 頂點鏈表，其中 <code>[]</code>、<code>[Comment]</code> 是有效的，但 <code>null, [null], [Comment, null]</code> 就不是。</li></ul>`,9)),a("p",null,[s[7]||(s[7]=a("em",null,"列表2",-1)),s[8]||(s[8]=n(" 包括一系列用於Blog API 的 ",-1)),s[9]||(s[9]=a("code",null,"curl",-1)),s[10]||(s[10]=n(" 命令，它們會使用 mutation 填充圖然後查詢圖以便獲取數據。要運行它們，按照 ",-1)),l(p,{href:"https://github.com/graphql/graphql-js"},{default:e(()=>[...s[6]||(s[6]=[n("topliceanu/graphql-go-example",-1)])]),_:1}),s[11]||(s[11]=n(" 倉庫中的指令編譯並運行服務。",-1))]),s[38]||(s[38]=t(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># 創建用户 1、2 和 3 的更改。更改和查詢類似，在該情景中我們檢索新創建用户的 id 和 email。</span></span>
<span class="line"><span>curl -XPOST http://vm:8080/graphql -d &#39;mutation {createUser(email:&quot;user1@x.co&quot;){id, email}}&#39;</span></span>
<span class="line"><span>curl -XPOST http://vm:8080/graphql -d &#39;mutation {createUser(email:&quot;user2@x.co&quot;){id, email}}&#39;</span></span>
<span class="line"><span>curl -XPOST http://vm:8080/graphql -d &#39;mutation {createUser(email:&quot;user3@x.co&quot;){id, email}}&#39;</span></span>
<span class="line"><span># 為用户添加博文的更改。為了和模式匹配我們需要檢索他們的 id，否則會出現錯誤。</span></span>
<span class="line"><span>curl -XPOST http://vm:8080/graphql -d &#39;mutation {createPost(user:1,title:&quot;post1&quot;,body:&quot;body1&quot;){id}}&#39;</span></span>
<span class="line"><span>curl -XPOST http://vm:8080/graphql -d &#39;mutation {createPost(user:1,title:&quot;post2&quot;,body:&quot;body2&quot;){id}}&#39;</span></span>
<span class="line"><span>curl -XPOST http://vm:8080/graphql -d &#39;mutation {createPost(user:2,title:&quot;post3&quot;,body:&quot;body3&quot;){id}}&#39;</span></span>
<span class="line"><span># 博文所有評論的更改。\`createComment\` 需要用户 id，標題和正文。看列表 1 的模式。</span></span>
<span class="line"><span>curl -XPOST http://vm:8080/graphql -d &#39;mutation {createComment(user:2,post:1,title:&quot;comment1&quot;,body:&quot;comment1&quot;){id}}&#39;</span></span>
<span class="line"><span>curl -XPOST http://vm:8080/graphql -d &#39;mutation {createComment(user:1,post:3,title:&quot;comment2&quot;,body:&quot;comment2&quot;){id}}&#39;</span></span>
<span class="line"><span>curl -XPOST http://vm:8080/graphql -d &#39;mutation {createComment(user:3,post:3,title:&quot;comment3&quot;,body:&quot;comment3&quot;){id}}&#39;</span></span>
<span class="line"><span># 讓用户 3 關注用户 1 和用户 2 的更改。注意 \`follow\` 更改只返回一個布爾值而不需要指定。</span></span>
<span class="line"><span>curl -XPOST http://vm:8080/graphql -d &#39;mutation {follow(follower:3, followee:1)}&#39;</span></span>
<span class="line"><span>curl -XPOST http://vm:8080/graphql -d &#39;mutation {follow(follower:3, followee:2)}&#39;</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 用户獲取用户 1 所有數據的查詢。</span></span>
<span class="line"><span>curl -XPOST http://vm:8080/graphql -d &#39;{user(id:1)}&#39;</span></span>
<span class="line"><span># 用户獲取用户 2 和用户 1 的關注者的查詢。</span></span>
<span class="line"><span>curl -XPOST http://vm:8080/graphql -d &#39;{user(id:2){followers{id, email}}}&#39;</span></span>
<span class="line"><span>curl -XPOST http://vm:8080/graphql -d &#39;{user(id:1){followers{id, email}}}&#39;</span></span>
<span class="line"><span># 檢測用户 2 是否被用户 1 關注的查詢。如果是，檢索用户 1 的 email，否則返回空。</span></span>
<span class="line"><span>curl -XPOST http://vm:8080/graphql -d &#39;{user(id:2){follower(id:1){email}}}&#39;</span></span>
<span class="line"><span># 返回用户 3 關注的所有用户 id 和 email 的查詢。</span></span>
<span class="line"><span>curl -XPOST http://vm:8080/graphql -d &#39;{user(id:3){followees{id, email}}}&#39;</span></span>
<span class="line"><span># 如果用户 3 被用户 1 關注，就獲取用户 3 email 的查詢。</span></span>
<span class="line"><span>curl -XPOST http://vm:8080/graphql -d &#39;{user(id:1){followee(id:3){email}}}&#39;</span></span>
<span class="line"><span># 獲取用户 1 的第二篇博文的查詢，檢索它的標題和正文。如果博文 2 不是由用户 1 創建的，就會返回空。</span></span>
<span class="line"><span>curl -XPOST http://vm:8080/graphql -d &#39;{user(id:1){post(id:2){title,body}}}&#39;</span></span>
<span class="line"><span># 獲取用户 1 的所有博文的所有數據的查詢。</span></span>
<span class="line"><span>curl -XPOST http://vm:8080/graphql -d &#39;{user(id:1){posts{id,title,body}}}&#39;</span></span>
<span class="line"><span># 獲取寫博文 2 用户的查詢，如果博文 2 是由 用户 1 撰寫；一個現實語言靈活性的例證。</span></span>
<span class="line"><span>curl -XPOST http://vm:8080/graphql -d &#39;{user(id:1){post(id:2){user{id,email}}}}&#39;</span></span></code></pre></div><p><em>列表2</em></p><p>通過仔細設計 mutation 和類型屬性，可以實現強大而富有表達力的查詢。</p><h3 id="設計-postgresql-資料庫" tabindex="-1">設計 PostgreSQL 資料庫 <a class="header-anchor" href="#設計-postgresql-資料庫" aria-label="Permalink to “設計 PostgreSQL 資料庫”">​</a></h3><p>關係型資料庫的設計，一如以往，由避免數據冗餘的需求驅動。選擇該方式有兩個原因：</p><ol><li>表明實現 GraphQL API 不需要定製化的資料庫技術或者學習和使用新的設計技巧。</li><li>表明 GraphQL API 能在現有的資料庫之上創建，更具體地説，最初設計用於 REST 後端甚至傳統的呈現 HTML 站點的服務器端資料庫。</li></ol><p>閲讀 <em>附錄1</em> 瞭解關於關係型和圖資料庫在構建 GraphQL API 方面的區別。<em>列表3</em> 顯示了用於創建新資料庫的 SQL 命令。資料庫模式和 GraphQL 模式相對應。為了支持 <code>follow/unfollow</code> 更改，需要添加 <code>followers</code> 關係。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>CREATE TABLE IF NOT EXISTS users (</span></span>
<span class="line"><span>  id SERIAL PRIMARY KEY,</span></span>
<span class="line"><span>  email VARCHAR(100) NOT NULL</span></span>
<span class="line"><span>);</span></span>
<span class="line"><span>CREATE TABLE IF NOT EXISTS posts (</span></span>
<span class="line"><span>  id SERIAL PRIMARY KEY,</span></span>
<span class="line"><span>  user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,</span></span>
<span class="line"><span>  title VARCHAR(200) NOT NULL,</span></span>
<span class="line"><span>  body TEXT NOT NULL</span></span>
<span class="line"><span>);</span></span>
<span class="line"><span>CREATE TABLE IF NOT EXISTS comments (</span></span>
<span class="line"><span>  id SERIAL PRIMARY KEY,</span></span>
<span class="line"><span>  user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,</span></span>
<span class="line"><span>  post_id INTEGER NOT NULL REFERENCES posts(id) ON DELETE CASCADE,</span></span>
<span class="line"><span>  title VARCHAR(200) NOT NULL,</span></span>
<span class="line"><span>  body TEXT NOT NULL</span></span>
<span class="line"><span>);</span></span>
<span class="line"><span>CREATE TABLE IF NOT EXISTS followers (</span></span>
<span class="line"><span>  follower_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,</span></span>
<span class="line"><span>  followee_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,</span></span>
<span class="line"><span>  PRIMARY KEY(follower_id, followee_id)</span></span>
<span class="line"><span>);</span></span></code></pre></div><p><em>列表3</em></p><h3 id="golang-api-實現" tabindex="-1">Golang API 實現 <a class="header-anchor" href="#golang-api-實現" aria-label="Permalink to “Golang API 實現”">​</a></h3>`,10)),a("p",null,[s[13]||(s[13]=n("本項目使用的用 Go 實現的 GraphQL 語法解析器是 ",-1)),s[14]||(s[14]=a("code",null,"github.com/graphql-go/graphql",-1)),s[15]||(s[15]=n("。它包括一個查詢解析器，但不包括模式解析器。這要求開發者利用庫提供的結構使用 Go 構建 GraphQL 模式。這和 ",-1)),l(p,{href:"https://github.com/graphql/graphql-js"},{default:e(()=>[...s[12]||(s[12]=[n("nodejs 實現",-1)])]),_:1}),s[16]||(s[16]=n(" 不同，後者提供了一個模式解析器併為數據獲取暴露了鈎子。因此 ",-1)),s[17]||(s[17]=a("em",null,"列表1",-1)),s[18]||(s[18]=n(" 中的模式只是作為指導使用，需要轉化為 Golang 代碼。然而，這個_“限制”_提供了與抽象級別對等的機會，並且瞭解模式如何和用於檢索數據的圖遍歷模型相關。",-1)),s[19]||(s[19]=a("em",null,"列表4",-1)),s[20]||(s[20]=n(" 顯示了 ",-1)),s[21]||(s[21]=a("code",null,"Comment",-1)),s[22]||(s[22]=n(" 頂點類型的實現：",-1))]),s[39]||(s[39]=t(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>var CommentType = graphql.NewObject(graphql.ObjectConfig{</span></span>
<span class="line"><span>	Name: &quot;Comment&quot;,</span></span>
<span class="line"><span>	Fields: graphql.Fields{</span></span>
<span class="line"><span>		&quot;id&quot;: &amp;graphql.Field{</span></span>
<span class="line"><span>			Type: graphql.NewNonNull(graphql.ID),</span></span>
<span class="line"><span>			Resolve: func(p graphql.ResolveParams) (interface{}, error) {</span></span>
<span class="line"><span>				if comment, ok := p.Source.(*Comment); ok == true {</span></span>
<span class="line"><span>					return comment.ID, nil</span></span>
<span class="line"><span>				}</span></span>
<span class="line"><span>				return nil, nil</span></span>
<span class="line"><span>			},</span></span>
<span class="line"><span>		},</span></span>
<span class="line"><span>		&quot;title&quot;: &amp;graphql.Field{</span></span>
<span class="line"><span>			Type: graphql.NewNonNull(graphql.String),</span></span>
<span class="line"><span>			Resolve: func(p graphql.ResolveParams) (interface{}, error) {</span></span>
<span class="line"><span>				if comment, ok := p.Source.(*Comment); ok == true {</span></span>
<span class="line"><span>					return comment.Title, nil</span></span>
<span class="line"><span>				}</span></span>
<span class="line"><span>				return nil, nil</span></span>
<span class="line"><span>			},</span></span>
<span class="line"><span>		},</span></span>
<span class="line"><span>		&quot;body&quot;: &amp;graphql.Field{</span></span>
<span class="line"><span>			Type: graphql.NewNonNull(graphql.ID),</span></span>
<span class="line"><span>			Resolve: func(p graphql.ResolveParams) (interface{}, error) {</span></span>
<span class="line"><span>				if comment, ok := p.Source.(*Comment); ok == true {</span></span>
<span class="line"><span>					return comment.Body, nil</span></span>
<span class="line"><span>				}</span></span>
<span class="line"><span>				return nil, nil</span></span>
<span class="line"><span>			},</span></span>
<span class="line"><span>		},</span></span>
<span class="line"><span>	},</span></span>
<span class="line"><span>})</span></span>
<span class="line"><span>func init() {</span></span>
<span class="line"><span>	CommentType.AddFieldConfig(&quot;user&quot;, &amp;graphql.Field{</span></span>
<span class="line"><span>		Type: UserType,</span></span>
<span class="line"><span>		Resolve: func(p graphql.ResolveParams) (interface{}, error) {</span></span>
<span class="line"><span>			if comment, ok := p.Source.(*Comment); ok == true {</span></span>
<span class="line"><span>				return GetUserByID(comment.UserID)</span></span>
<span class="line"><span>			}</span></span>
<span class="line"><span>			return nil, nil</span></span>
<span class="line"><span>		},</span></span>
<span class="line"><span>	})</span></span>
<span class="line"><span>	CommentType.AddFieldConfig(&quot;post&quot;, &amp;graphql.Field{</span></span>
<span class="line"><span>		Type: PostType,</span></span>
<span class="line"><span>		Args: graphql.FieldConfigArgument{</span></span>
<span class="line"><span>			&quot;id&quot;: &amp;graphql.ArgumentConfig{</span></span>
<span class="line"><span>				Description: &quot;Post ID&quot;,</span></span>
<span class="line"><span>				Type:        graphql.NewNonNull(graphql.ID),</span></span>
<span class="line"><span>			},</span></span>
<span class="line"><span>		},</span></span>
<span class="line"><span>		Resolve: func(p graphql.ResolveParams) (interface{}, error) {</span></span>
<span class="line"><span>			i := p.Args[&quot;id&quot;].(string)</span></span>
<span class="line"><span>			id, err := strconv.Atoi(i)</span></span>
<span class="line"><span>			if err != nil {</span></span>
<span class="line"><span>				return nil, err</span></span>
<span class="line"><span>			}</span></span>
<span class="line"><span>			return GetPostByID(id)</span></span>
<span class="line"><span>		},</span></span>
<span class="line"><span>	})</span></span>
<span class="line"><span>}</span></span></code></pre></div><p><em>列表4</em></p><p>正如 <em>列表1</em> 中的模式，<code>Comment</code> 類型是靜態定義的一個有三個屬性的結構體：<code>id</code>、<code>title</code> 和 <code>body</code>。為了避免循環依賴，動態定義了 <code>user</code> 和 <code>post</code> 兩個其它屬性。</p><p>Go 並不適用於這種動態建模，它只支持一些類型檢查，代碼中大部分變量都是 <code>interface{}</code> 類型，在使用之前都需要進行類型斷言。<code>CommentType</code> 是一個 <code>graphql.Object</code> 類型的變量，它的屬性是 <code>graphql.Field</code> 類型。因此，GraphQL DSL 和 Go 中使用的數據結構並沒有直接的轉換。</p><p>每個字段的 <code>resolve</code> 函數暴露了 <code>Source</code> 參數，它是表示遍歷時前一個節點的數據類型頂點。<code>Comment</code> 的所有屬性都有作為 source 的當前 <code>CommentType</code> 頂點。檢索<code>id</code>、<code>title</code> 和 <code>body</code> 是一個直接屬性訪問，而檢索 <code>user</code> 和 <code>post</code> 要求圖遍歷，也需要資料庫查詢。由於它們非常簡單，這篇文章並沒有介紹這些 SQL 查詢，但在_參考文獻_部分列出的 github 倉庫中有。</p><h3 id="普通場景下和-rest-的對比" tabindex="-1">普通場景下和 REST 的對比 <a class="header-anchor" href="#普通場景下和-rest-的對比" aria-label="Permalink to “普通場景下和 REST 的對比”">​</a></h3><p>在這一部分，我們會展示一個普通的Blog文章呈現場景，並比較 REST 和 GraphQL 的實現。關注重點會放在入站/出站請求數量，因為這些是造成頁面呈現延遲的最主要原因。</p><p>場景：呈現一個Blog文章頁面。它應該包含關於作者（email）、Blog文章（標題、正文）、所有評論（標題、正文）以及評論人是否關注Blog文章作者的信息。<em>圖1</em> 和 <em>圖2</em> 顯示了客户端 SPA、API 服務器以及資料庫之間的交互，一個是 REST API、另一個對應是 GraphQL API。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>+------+                  +------+                  +--------+</span></span>
<span class="line"><span>|client|                  |server|                  |database|</span></span>
<span class="line"><span>+--+---+                  +--+---+                  +----+---+</span></span>
<span class="line"><span>   |      GET /blogs/:id     |                           |</span></span>
<span class="line"><span>1\\. +-------------------------&gt;  SELECT * FROM blogs...   |</span></span>
<span class="line"><span>   |                         +---------------------------&gt;</span></span>
<span class="line"><span>   |                         &lt;---------------------------+</span></span>
<span class="line"><span>   &lt;-------------------------+                           |</span></span>
<span class="line"><span>   |                         |                           |</span></span>
<span class="line"><span>   |     GET /users/:id      |                           |</span></span>
<span class="line"><span>2\\. +-------------------------&gt;  SELECT * FROM users...   |</span></span>
<span class="line"><span>   |                         +---------------------------&gt;</span></span>
<span class="line"><span>   |                         &lt;---------------------------+</span></span>
<span class="line"><span>   &lt;-------------------------+                           |</span></span>
<span class="line"><span>   |                         |                           |</span></span>
<span class="line"><span>   | GET /blogs/:id/comments |                           |</span></span>
<span class="line"><span>3\\. +-------------------------&gt; SELECT * FROM comments... |</span></span>
<span class="line"><span>   |                         +---------------------------&gt;</span></span>
<span class="line"><span>   |                         &lt;---------------------------+</span></span>
<span class="line"><span>   &lt;-------------------------+                           |</span></span>
<span class="line"><span>   |                         |                           |</span></span>
<span class="line"><span>   | GET /users/:id/followers|                           |</span></span>
<span class="line"><span>4\\. +-------------------------&gt; SELECT * FROM followers.. |</span></span>
<span class="line"><span>   |                         +---------------------------&gt;</span></span>
<span class="line"><span>   |                         &lt;---------------------------+</span></span>
<span class="line"><span>   &lt;-------------------------+                           |</span></span>
<span class="line"><span>   |                         |                           |</span></span>
<span class="line"><span>   +                         +                           +</span></span></code></pre></div><p><em>圖1</em></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>+------+                  +------+                  +--------+</span></span>
<span class="line"><span>|client|                  |server|                  |database|</span></span>
<span class="line"><span>+--+---+                  +--+---+                  +----+---+</span></span>
<span class="line"><span>   |      GET /graphql       |                           |</span></span>
<span class="line"><span>1\\. +-------------------------&gt;  SELECT * FROM blogs...   |</span></span>
<span class="line"><span>   |                         +---------------------------&gt;</span></span>
<span class="line"><span>   |                         &lt;---------------------------+</span></span>
<span class="line"><span>   |                         |                           |</span></span>
<span class="line"><span>   |                         |                           |</span></span>
<span class="line"><span>   |                         |                           |</span></span>
<span class="line"><span>2\\. |                         |  SELECT * FROM users...   |</span></span>
<span class="line"><span>   |                         +---------------------------&gt;</span></span>
<span class="line"><span>   |                         &lt;---------------------------+</span></span>
<span class="line"><span>   |                         |                           |</span></span>
<span class="line"><span>   |                         |                           |</span></span>
<span class="line"><span>   |                         |                           |</span></span>
<span class="line"><span>3\\. |                         | SELECT * FROM comments... |</span></span>
<span class="line"><span>   |                         +---------------------------&gt;</span></span>
<span class="line"><span>   |                         &lt;---------------------------+</span></span>
<span class="line"><span>   |                         |                           |</span></span>
<span class="line"><span>   |                         |                           |</span></span>
<span class="line"><span>   |                         |                           |</span></span>
<span class="line"><span>4\\. |                         | SELECT * FROM followers.. |</span></span>
<span class="line"><span>   |                         +---------------------------&gt;</span></span>
<span class="line"><span>   |                         &lt;---------------------------+</span></span>
<span class="line"><span>   &lt;-------------------------+                           |</span></span>
<span class="line"><span>   |                         |                           |</span></span>
<span class="line"><span>   +                         +                           +</span></span></code></pre></div><p><em>圖2</em></p><p><em>列表5</em> 是一條用於獲取所有呈現博文所需數據的簡單 GraphQL 查詢。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>  user(id: 1) {</span></span>
<span class="line"><span>    email</span></span>
<span class="line"><span>    followers</span></span>
<span class="line"><span>    post(id: 1) {</span></span>
<span class="line"><span>      title</span></span>
<span class="line"><span>      body</span></span>
<span class="line"><span>      comments {</span></span>
<span class="line"><span>        id</span></span>
<span class="line"><span>        title</span></span>
<span class="line"><span>        user {</span></span>
<span class="line"><span>          id</span></span>
<span class="line"><span>          email</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>      }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p><em>列表5</em></p><p>對於這種情況，對資料庫的查詢次數是故意相同的，但是到 API 服務器的 HTTP 請求已經減少到只有一個。我們認為在這種類型的應用程序中通過互聯網的 HTTP 請求是最昂貴的。</p><p>為了利用 GraphQL 的優勢，後端並不需要進行特別設計，從 REST 到 GraphQL 的轉換可以逐步完成。這使得可以測量性能提升和優化。從這一點，API 設計者可以開始優化（潛在的合併） SQL 查詢從而提高性能。緩存的機會在資料庫和 API 級別都大大增加。</p><p>SQL 之上的抽象（例如 ORM 層）通常會和 <code>n+1</code> 問題相牴觸。在 REST 示例的步驟 4 中，客户端可能不得不在單獨的請求中為每個評論的作者請求關注狀態。這是因為在 REST 中沒有標準的方式來表達兩個以上資源之間的關係，而 GraphQL 旨在通過使用嵌套查詢來防止這類問題。這裏我們通過獲取用户的所有關注者來作弊。我們向客户提出瞭如何確定評論並關注了作者的用户的邏輯。</p><p>另一個區別是獲取比客户端所需更多的數據，以免破壞 REST 資源抽象。這對於用於解析和存儲不需要數據的帶寬消耗和電池壽命非常重要。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>GraphQL 是 REST 的一個可用替代方案，因為：</p><ul><li>儘管設計 API 更加困難，但該過程可以逐步完成。也是由於這個原因，從 REST 轉換到 GraphQL 非常容易，兩個流程可以沒有任何問題地共存。</li><li>在網絡請求方面更加高效，即使是類似本Blog中的簡單實現。它還提供了更多查詢優化和結果緩存的機會。</li><li>在用於解析結果的帶寬消耗和 CPU 週期方面它更加高效，因為它只返回呈現頁面所需的數據。</li></ul><p>REST 仍然非常有用，如果：</p><ul><li>你的 API 非常簡單，只有少量的資源或者資源之間關係簡單。</li><li>在你的組織中已經在使用 REST API，而且你已經配置好了所有工具，或者你的客户希望獲取 REST API。</li><li>你有複雜的 ACL（LCTT 譯註：Access Control List） 策略。在Blog例子中，可能的功能是允許用户良好地控制誰能查看他們的電子郵箱、Blog、特定Blog的評論、他們關注了誰，等等。優化數據獲取同時檢查複雜的業務規則可能會更加困難。</li></ul><h3 id="附錄1-圖資料庫和高效數據存儲" tabindex="-1">附錄1：圖資料庫和高效數據存儲 <a class="header-anchor" href="#附錄1-圖資料庫和高效數據存儲" aria-label="Permalink to “附錄1：圖資料庫和高效數據存儲”">​</a></h3><p>儘管將其應用領域數據想像為一個圖非常直觀，正如這篇博文介紹的那樣，但是支持這種接口的高效數據存儲問題仍然沒有解決。</p><p>近年來圖資料庫變得越來越流行。通過將 GraphQL 查詢轉換為特定的圖資料庫查詢語言從而延遲解決請求的複雜性似乎是一種可行的方案。</p><p>問題是和關係型資料庫相比，圖並不是一種高效的數據結構。圖中一個頂點可能有到任何其它頂點的連接，訪問模式比較難以預測因此提供了較少的優化機會。</p><p>例如緩存的問題，為了快速訪問需要將哪些頂點保存在內存中？通用緩存算法在圖遍歷場景中可能沒那麼高效。</p><p>資料庫分片問題：把資料庫切分為更小、沒有交叉的資料庫並保存到獨立的硬件。在學術上，最小切割的圖劃分問題已經得到了很好的理解，但可能是次優的，而且由於病態的最壞情況可能導致高度不平衡切割。</p><p>在關係型資料庫中，數據被建模為記錄（行或者元組）和列，表和資料庫名稱都只是簡單的命名空間。大部分資料庫都是面向行的，意味着每個記錄都是一個連續的內存塊，一個表中的所有記錄在磁盤上一個接一個地整齊地打包（通常按照某個關鍵列排序）。這非常高效，因為這是物理存儲最優的工作方式。HDD 最昂貴的操作是將磁頭移動到磁盤上的另一個扇區，因此最小化此類訪問非常重要。</p><p>很有可能如果應用程序對一條特定記錄感興趣，它需要獲取整條記錄，而不僅僅是記錄中的其中一列。也很有可能如果應用程序對一條記錄感興趣，它也會對該記錄周圍的記錄感興趣，例如全表掃描。這兩點使得關係型資料庫相當高效。然而，也是因為這個原因，關係型資料庫的最差使用場景就是總是隨機訪問所有數據。圖資料庫正是如此。</p><p>隨着支持更快隨機訪問的 SSD 驅動器的出現，更便宜的內存使得緩存大部分圖資料庫成為可能，更好的優化圖緩存和分區的技術，圖資料庫開始成為可選的存儲解決方案。大部分大公司也使用它：Facebook 有 Social Graph，Google 有 Knowledge Graph。</p><hr>`,34)),a("p",null,[s[24]||(s[24]=n("via: ",-1)),l(p,{href:"http://alexandrutopliceanu.ro/post/graphql-with-go-and-postgresql"},{default:e(()=>[...s[23]||(s[23]=[n("http://alexandrutopliceanu.ro/post/graphql-with-go-and-postgresql",-1)])]),_:1})]),a("p",null,[s[28]||(s[28]=n("作者：",-1)),l(p,{href:"https://github.com/topliceanu"},{default:e(()=>[...s[25]||(s[25]=[n("Alexandru Topliceanu",-1)])]),_:1}),s[29]||(s[29]=n(" 譯者：",-1)),l(p,{href:"https://github.com/ictlyh"},{default:e(()=>[...s[26]||(s[26]=[n("ictlyh",-1)])]),_:1}),s[30]||(s[30]=n(" 校對：",-1)),l(p,{href:"https://github.com/wxy"},{default:e(()=>[...s[27]||(s[27]=[n("wxy",-1)])]),_:1})]),a("p",null,[s[33]||(s[33]=n("本文由 ",-1)),l(p,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[31]||(s[31]=[n("LCTT",-1)])]),_:1}),s[34]||(s[34]=n(" 原創編譯，",-1)),l(p,{href:"https://linux.cn/"},{default:e(()=>[...s[32]||(s[32]=[n("Linux中國",-1)])]),_:1}),s[35]||(s[35]=n(" 榮譽推出",-1))])])}const P=i(c,[["render",g]]);export{f as __pageData,P as default};
